-- Lua 5.1 pattern matching edge cases.
local function p(...)
  local t = table.pack and table.pack(...) or {n = select('#', ...), ...}
  local out = {}
  for i = 1, t.n do out[i] = tostring(t[i]) end
  print(table.concat(out, " | "))
end
local function pp(f, ...) p(pcall(f, ...)) end

p(string.find("hello world", "o w"))
p(string.find("hello", "l+"))
p(string.find("hello", "", 10))
p(string.find("hello", "", 6))
