for k, v in string.gmatch("a=1, b=2, c=3", "(%w+)=(%w+)") do io.write(k, v, ";") end print()
for w in string.gmatch("one two  three", "%a+") do io.write("<", w, ">") end print()
for pos in string.gmatch("abc", "()") do io.write(pos, " ") end print()
for x in string.gmatch("abc", "^a") do io.write("[", x, "]") end print()
for a, b in string.gmatch("aXbXc", "(%a)()") do io.write(a, b, " ") end print()
for x in string.gmatch("", ".*") do io.write("empty:", #x) end print()
local it = string.gmatch("a1b2", "%a(%d)")
p(it(), it(), it())
p(string.byte("abc", 0), string.byte("abc", -1), string.byte("abc", 2, 10), string.byte(""))
p(string.sub("hello", 2), string.sub("hello", -3), string.sub("hello", 2, -2), string.sub("hello", 0), string.sub("hello", 10), string.sub("hello", -100, 2), string.sub("hello", 3, 2))
p(string.upper("aBc\255"), string.lower("AbC\200"), string.reverse("abc"), string.reverse(""))
p(string.len("\0\0"), #"abc", ("x"):rep(3), string.rep("x", 0), string.rep("x", -1))
p(string.format("%s", string.find("x", "x", 2^31)))
p(string.find("abc", "c", 2^53))
p(string.find("abc", "a", -2^53))
-- long subjects and backtracking limits
local long = string.rep("a", 10000)
p(#string.match(long, ".-$"), #string.gsub(long, "a", "bb"))
pp(string.match, string.rep("a", 300000), string.rep("a?", 300000) .. string.rep("a", 300000))
p(select("#", string.byte(string.rep("x", 100), 1, -1)))
